"""Validate completed exploratory artifacts and produce a factual study report."""
import json
from pathlib import Path
import numpy as np
from .exploratory_ga7_study import OUT

def main():
    batch=json.loads((OUT/'batch_runtime.json').read_text())
    assert len(batch['jobs'])==10 and all(j['exit']==0 for j in batch['jobs']),batch
    rows=[];summaries=[]
    for s in range(1,6):
        arms={}
        for arm in ('evolved','frozen'):
            stem=f'scenario_{s}_{arm}'
            d=json.loads((OUT/f'{stem}.json').read_text())
            assert d['sessions']==1260 and d['stocks']==500
            assert d['initial_native_chromosomes']==54
            assert len(d['annual_joint_evolution'])==(4 if arm=='evolved' else 0)
            for e in d['annual_joint_evolution']:
                assert e['training_maturity_max']<e['session']
                assert len(e['descendants'])==4
                (OUT/f'scenario_{s}_checkpoint_{e["session"]}.json').write_text(json.dumps(e,indent=2))
                assert 0<e['size_multiplier']<=1
            nav=json.loads((OUT/f'{stem}_nav.json').read_text())
            assert len(nav)==1260 and all(np.isfinite(r[1]) and r[1]>0 and np.isfinite(r[2]) and r[2]>=-1e-7 for r in nav)
            learned=json.loads((OUT/f'{stem}_learning.json').read_text())
            assert learned['maturity_max']<learned['asof_session']
            assert sum(x['samples'] for x in learned['chromosomes'])==learned['strict_past_samples']
            children={c['id'] for e in d['annual_joint_evolution'] for c in e['descendants']}
            d['descendant_matured_samples']=sum(x['samples'] for x in learned['chromosomes'] if x['id'] in children)
            d['descendants_with_matured_samples']=sum(x['samples']>0 for x in learned['chromosomes'] if x['id'] in children)
            arms[arm]=d;summaries.append(d)
        a,b=arms['evolved'],arms['frozen'];m=a['synthetic_market_index']
        rows.append({'scenario':s,'evolved_cagr_pct':a['portfolio']['cagr_pct'],'frozen_cagr_pct':b['portfolio']['cagr_pct'],'market_cagr_pct':m['cagr_pct'],'evolved_mdd_pct':a['portfolio']['mdd_pct'],'frozen_mdd_pct':b['portfolio']['mdd_pct'],'evolved_vs_frozen_pp':a['portfolio']['cagr_pct']-b['portfolio']['cagr_pct'],'evolved_vs_market_pp':a['portfolio']['cagr_pct']-m['cagr_pct'],'target_met':a['portfolio']['cagr_pct']-m['cagr_pct']>=20 and a['portfolio']['mdd_pct']<=20})
    totals={'status':'EXPLORATORY_COMPLETED_NOT_PRODUCTION_CERTIFIED','wall_seconds':batch['wall_seconds'],'scenario_arms':10,'stock_sessions':500*1260*10,'funded_fills':sum(d['fills'] for d in summaries),'native_matured_shadows':sum(sum(d['matured_shadows'].values()) for d in summaries),'learned_choices':sum(d['learned_choices'] for d in summaries),'joint_checkpoints':sum(len(d['annual_joint_evolution']) for d in summaries),'descendant_matured_samples':sum(d['descendant_matured_samples'] for d in summaries),'descendants_with_matured_samples':sum(d['descendants_with_matured_samples'] for d in summaries),'native_descendants':sum(d['native_chromosomes_including_descendants']-54 for d in summaries),'evolved_beats_frozen_scenarios':sum(r['evolved_vs_frozen_pp']>0 for r in rows),'target_scenarios':sum(r['target_met'] for r in rows),'scenarios':rows,'verification':'All 10 arms complete; NAV finite and positive; cash nonnegative; checkpoint and learner maturity strictly prior; 4 descendants/checkpoint; 54 source chromosomes/arm.'}
    archive=OUT/'raw_checkpoint_archive';archive.mkdir(exist_ok=True)
    for checkpoint in OUT.glob('checkpoint_*.json'):
        checkpoint.rename(archive/checkpoint.name)
    (OUT/'aggregate.json').write_text(json.dumps(totals,indent=2))
    lines=['# Exploratory MTS GA7: completed synthetic experiment','', '**Research/exploratory only. Not production-certified, PIT-certified, or evidence of live-market transferability.**','',f"Completed five independent scenarios × 500 stocks × 1,260 sessions × two funded arms. Measured batch wall time: **{batch['wall_seconds']/60:.2f} minutes** with up to four workers (two initially, then two additional workers for independent scenarios). Individual replay times exclude final artifact serialization; batch time includes worker startup and artifact output.",'','| Scenario | Evolved CAGR | Frozen CAGR | Synthetic market CAGR | Evolved MDD | Frozen MDD | Evolved − frozen |','|---|---:|---:|---:|---:|---:|---:|']
    for r in rows:lines.append(f"| {r['scenario']} | {r['evolved_cagr_pct']:.2f}% | {r['frozen_cagr_pct']:.2f}% | {r['market_cagr_pct']:.2f}% | {r['evolved_mdd_pct']:.2f}% | {r['frozen_mdd_pct']:.2f}% | {r['evolved_vs_frozen_pp']:+.2f} pp |")
    lines+=['',f"The pre-existing objective (≥20 percentage points CAGR advantage over the synthetic market with ≤20% MDD) was met in **{totals['target_scenarios']}/5** scenarios. No performance threshold was relaxed. The evolved system exceeded frozen-control CAGR in {totals['evolved_beats_frozen_scenarios']}/5 scenarios; its current matured-shadow proxy fitness did not deliver a consistent funded improvement.",'',f"Executed {totals['funded_fills']:,} funded fills and matured {totals['native_matured_shadows']:,} native shadows across both arms. Evolved arms made {totals['learned_choices']:,} selections from matured evidence and completed {totals['joint_checkpoints']} annual joint checkpoints, creating {totals['native_descendants']} descendants across independent scenarios.",'','Each arm starts with one $100,000 funded bank, 10bp fees per side, next-open execution, T+1 sale settlement, and 10% entry cap. Cash earns zero. Incumbents retain their native held-state management; all native shadows have independent fills, entry prices, peaks, and exit maturity. Filled ownership/share reconciliation runs every session. Open terminal positions are marked to close; pending orders are not forced to execute outside the panel.','', 'The initial cohort is the previous identity-only sample: 26 authentic GA6 and 28 authentic GA7 definitions. This is not an exhaustive library run. Source catalogue/cohort definitions are preserved. Exploratory mapping explicitly hypothesizes `NICHE-xxxx → PIT-NICHE-xxxx` by ordinal suffix; it is not an authenticated identity bridge, empirically validated alignment, or provenance repair. No PIT sidecar was fabricated. The original certification preflight remains blocked; the explicitly exploratory runner uses this disclosed mapping.','', 'At sessions 252/504/756/1008, joint search runs 32 allocation/manager candidates over six generations. Fitness uses strict-past native matured shadow mean returns and uncertainty, not candidate funded-portfolio replay. Two parents per native family produce four children per checkpoint by same-niche crossover plus bounded native trading-gene mutations. GA6 mutates hold/exit/scaling thresholds; GA7 mutates entry thresholds and size. Each child has a new registered full-genome identity, its own evidence history and a recorded training cutoff preceding first use. Sources remain unchanged. Descendants are forward-shadowed; no invented pre-birth outcomes are assigned. Library size grows from 54 to 70 in evolved arms.','', 'The manager evolves allocation weights, uncertainty penalty, and funded entry-size multiplier. Forty initial sessions permit deterministic cold-start rotation; thereafter unavailable or nonpositive learned edge abstains. Shadow entry sizes retain native semantics while funded size receives the manager multiplier. Learning ingests only exits matured strictly before the current session. Model/manager genes are frozen after session 1008; the predeclared online learner continues causally during the final forward year.','', 'The synthetic market index is the generator’s market_index.parquet; equal-weight synthetic 500-stock buy-and-hold is also reported. Neither is real SPY. Annual and full-period CAGR/MDD, matured-shadow EV (net return on each normalized shadow account), family coverage/PnL, cash exposure, native action counts, NAV, fills, source definitions, descendants and learning sufficient statistics are in the adjacent JSON files. Source model PIT provenance and feature value/native evaluator parity remain unverified. Synthetic dates are rebased to an order calendar after library freeze; this is not a historical backtest. Shadow totals include mirrored source strategies in both arms and correlated stock/session outcomes; they are executed replay counts, not independent validation samples. The two arms compare the combined learning/evolution system with the frozen baseline; they do not isolate separate learning, manager, and mutation contributions. Seeds are 7007 plus scenario number. No mapping sensitivity study or independently sealed replication was run.','', '| Scenario / arm | Runtime (s) | Fills | Matured shadows | Learned choices | Funded families |','|---|---:|---:|---:|---:|---|']
    for d in summaries:lines.append(f"| {d['scenario']} / {d['arm']} | {d['wall_seconds']:.2f} | {d['fills']:,} | {sum(d['matured_shadows'].values()):,} | {d['learned_choices']:,} | {', '.join(d['funded_families'])} |")
    lines+=['','A full-length replay exposed a residual-share accounting mismatch: the attribution book removed holdings at 1e-8 shares while the bank retained holdings above 1e-10. The book now uses the same 1e-10 threshold, and a 45-session repeated-reduction regression verifies retained ownership. The failed partial batch is preserved separately and excluded from completed-study runtime. The earlier 260-session breeding smoke completed in 58.41 seconds. The initial allocation-only partial batch was interrupted to add native breeding and is excluded from reported full-study runtime. Engineering time is not included in batch runtime.','', 'Reproduce from the repository root with the synthetic lab venv: `python -m discovery.competitive_ga.run_exploratory_ga7_batch --workers 4 --force`; then `python -m discovery.competitive_ga.report_exploratory_ga7`. The batch launcher sets native dependency paths. This run added two independent workers after the first pair; per-arm locks and completed-result reuse prevented duplicate replay. Existing archived native schema dependencies must be readable.']
    (OUT/'report.md').write_text('\n'.join(lines)+'\n')
    print(json.dumps(totals,indent=2))
if __name__=='__main__':main()
